import {
  addDoc,
  collection,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  updateDoc,
  doc,
  where,
} from "firebase/firestore";
import type { SupportNote } from "../../features/admin/types";

export type CreateNoteInput = {
  itineraryId: string;
  authorId: string;
  note: string;
};

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function createNote(input: CreateNoteInput): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "supportNotes"), {
    itineraryId: input.itineraryId,
    authorId: input.authorId,
    note: input.note,
    visibility: "internal",
    createdAt: serverTimestamp(),
    updatedAt: null,
  });
  return ref.id;
}

export async function updateNote(id: string, note: string): Promise<void> {
  const db = await getDb();
  await updateDoc(doc(db, "supportNotes", id), {
    note,
    updatedAt: serverTimestamp(),
  });
}

export async function listNotesByItinerary(itineraryId: string): Promise<(SupportNote & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "supportNotes"),
    where("itineraryId", "==", itineraryId),
    orderBy("createdAt", "desc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as SupportNote) }));
}

export async function listAllNotes(): Promise<(SupportNote & { id: string })[]> {
  const db = await getDb();
  const q = query(collection(db, "supportNotes"), orderBy("createdAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as SupportNote) }));
}
